import * as http from 'node:http';
function main(): void {
  const s = http.createServer((req: any, res: any) => { res.end('ok'); });
  s.on('listening', async () => {
    const r = await fetch('http://127.0.0.1:' + (s.address() as any).port + '/');
    console.log(await r.text());
    s.getConnections((err: any, n: number) => { console.log('conns', typeof n); });
    s.closeIdleConnections();
    s.closeAllConnections();
    s.ref(); s.unref();
    s.close(() => { console.log('closed'); });
  });
  s.listen(0, '127.0.0.1');
}
